function parseRoute(){const [id='nearby',q='']=location.hash.slice(1).split('?');const screen=screens.find(s=>s.id===id)||screens.find(s=>s.id==='nearby');const state=new URLSearchParams(q).get('state')||'base';return {id:screen.id,state:screen.states.includes(state)?state:'base'};}
function ActionIcon({done}){return <span className="action-icon" data-done={done} aria-hidden="true"><Plus/><Check/></span>}
function DockAddButton({children,onClick,...rest}){
 return <button {...rest} type="button" className="dock-add" onClick={onClick}>{children}</button>;
}
function Button({children,onClick,variant='',type='button',...rest}){return <button type={type} className={`button ${variant}`} onClick={onClick} {...rest}>{children}</button>}
function Field({label,name,value,onChange,type='text',maxLength=80,placeholder,options,errors={},forced=false}){const err=errors[name]||(forced?'Проверьте это поле перед сохранением':'');return <label className="field"><span id={`${name}-label`}>{label}</span>{options?<select aria-labelledby={`${name}-label`} value={value} onChange={e=>onChange(e.target.value)} aria-invalid={!!err} aria-describedby={err?`${name}-error`:undefined}><option value="" disabled hidden>Выберите {label.toLowerCase()}</option>{options.map(v=><option key={v} value={v}>{v}</option>)}</select>:<input aria-labelledby={`${name}-label`} name={name} type={type} value={value} onChange={e=>onChange(e.target.value)} maxLength={maxLength} placeholder={placeholder} autoComplete={name==='password'?'current-password':'off'} aria-invalid={!!err} aria-describedby={err?`${name}-error`:undefined}/>} {err&&<small className="field-error" id={`${name}-error`}>{err}</small>}</label>}
function App(){
 const [route,setRoute]=useState(parseRoute);const {id,state}=route; const screen=screens.find(s=>s.id===id);
 const [pets,setPets]=useState(initialPets);const [otherPets,setOtherPets]=useState([richie]);const [walks,setWalks]=useState(initialWalks);const [requests,setRequests]=useState(initialRequests);const [availableLocations,setLocations]=useState(locations);
 const [savedLocation,setSavedLocation]=useState(initialLocation);const [loc,setLoc]=useState(initialLocation);const [req,setReq]=useState({city:'Москва',district:'Коммунарка',complex:'Скандинавия'});
 const [petId,setPetId]=useState('bonya');const [walkId,setWalkId]=useState('w3');const [requestId,setRequestId]=useState('r1');
 const [petDraft,setPetDraft]=useState(['edit-pet','admin-edit'].includes(parseRoute().id)?initialPets[0]:{name:'',owner:'',breed:'',photo:'/dog-placeholder.webp'});const [draft,setDraft]=useState(defaultDraft);const [period,setPeriod]=useState('Все');const [tempPeriod,setTempPeriod]=useState('Все');const [query,setQuery]=useState('');const [customPlace,setCustomPlace]=useState('');
 const [platform,setPlatform]=useState('iPhone');const [formErrors,setErrors]=useState({});const [photoError,setPhotoError]=useState('');const [guided,setGuided]=useState(false);const [formReturn,setFormReturn]=useState('announce');const [photoReturn,setPhotoReturn]=useState('new-pet');
 const [linkVersion,setLinkVersion]=useState(()=>Number(sessionStorage.getItem('dogmeet.prototype.link-version'))||1);const [usedLink,setUsedLink]=useState(false);const [enabled,setEnabled]=useState(false);const [login,setLogin]=useState({user:'',password:''});const [toast,setToast]=useState('');
 const dialog=useRef(null);const heading=useRef(null);const timers=useRef([]);
 const routeRef=useRef(route);const toastRef=useRef(null);const toastTimer=useRef(null);const toastVersion=useRef(0);
 const nav=useRef({index:0,sequence:0,target:'',scroll:new Map(),opener:null,keyboard:false});
 const [backgroundId,setBackgroundId]=useState(()=>{let target=id;while(sheetIds.includes(target))target=parents[target]||'nearby';return target});
 const pageId=sheetIds.includes(id)?backgroundId:id;
 const capture=new URLSearchParams(location.search).has('capture');const sheet=sheetIds.includes(id);const pageScreen=screens.find(s=>s.id===pageId);
 const currentPet=(state==='shared'?pets.find(p=>p.shared):[...pets,...otherPets].find(p=>p.id===petId))||initialPets[0];
 const acceptParams=new URLSearchParams(location.hash.split('?')[1]||'');const invitedPet=[...pets,...otherPets].find(p=>p.id===acceptParams.get('pet'))||richie;
 const currentWalk=walks.find(w=>w.id===walkId)||initialWalks[2];const currentRequest=requests.find(r=>r.id===requestId)||initialRequests[0];
 const allPets=[...pets,...otherPets.filter(p=>!pets.some(own=>own.id===p.id))];const findPet=pid=>allPets.find(p=>p.id===pid)||initialPets.find(p=>p.id===pid)||richie;
 const navigate=useCallback(async(next,index)=>{
  const current=routeRef.current, n=nav.current;
  const target=`${index}:${next.id}:${next.state}`;
  if(n.target===target)return;
  n.target=target;
  const sequence=++n.sequence, keyboard=n.keyboard;
  skipPageTransition();
  const wasSheet=sheetIds.includes(current.id), willSheet=sheetIds.includes(next.id);
  const backwards=index<n.index;
  if(current.id!==next.id)timers.current.splice(0).forEach(clearTimeout);
  if(willSheet&&dialog.current?.classList.contains('is-closing')){
   dialog.current.getAnimations().forEach(a=>a.cancel());
   dialog.current.classList.remove('is-closing');
  }
  if(!wasSheet)n.scroll.set(n.index,window.scrollY);
  if(!wasSheet&&willSheet)n.opener=document.activeElement;
  if(wasSheet&&!willSheet){
   await closeSheet(dialog.current,keyboard);
   if(sequence!==n.sequence)return;
   dialog.current?.close();
  }
  if(sequence!==n.sequence)return;
  const photoId=((current.id==='pets'&&next.id==='pet')||(current.id==='pet'&&next.id==='pets'))
   ? (document.activeElement?.closest('.pet-row')?.querySelector('img')||document.querySelector('main .portrait'))?.dataset.petPhoto : null;
  const update=()=>{
   if(sequence!==n.sequence)return;
   routeRef.current=next;
   n.index=index;
   flushSync(()=>{
    if(!wasSheet)setBackgroundId(current.id);
    setRoute(next);setErrors({});setPhotoError('');
   });
   if(!willSheet){
    if(!wasSheet)window.scrollTo(0,backwards?n.scroll.get(index)||0:0);
    if(wasSheet&&n.opener?.isConnected){n.opener.focus({preventScroll:true});n.opener=null;}
    else heading.current?.focus({preventScroll:true});
   }
  };
  if(!wasSheet&&!willSheet&&current.id!==next.id){
   await transitionPage(update,{direction:directionFor(current.id,next.id,backwards),photoId,keyboard,target:next.id});
 }else{
  update();
  if(sequence===n.sequence&&!wasSheet&&!willSheet)fadeIn(document.querySelector('.scenario-content'),keyboard);
 }
 },[]);
 function go(target,nextState='base'){
 const next={id:target,state:nextState};
 const requested=parseRoute();
 if(requested.id===target&&requested.state===nextState)return;
  const fromSheet=sheetIds.includes(routeRef.current.id);
  if(fromSheet&&target===backgroundId){back();return;}
  const currentIndex=history.state?.dogmeetIndex??nav.current.index;
  const index=fromSheet?currentIndex:currentIndex+1;
  history[fromSheet?'replaceState':'pushState']({dogmeetIndex:index},'',`#${target}${nextState==='base'?'':`?state=${nextState}`}`);
  void navigate(next,index);
 }
 function back(){
  timers.current.splice(0).forEach(clearTimeout);
  if((history.state?.dogmeetIndex??0)>0)history.back();
  else{
   const target=parents[routeRef.current.id]||'nearby';
   history.replaceState({dogmeetIndex:0},'',`#${target}`);
   void navigate({id:target,state:'base'},0);
  }
 }
 function variant(s){
  const current=routeRef.current;
  history.replaceState(history.state,'',`#${current.id}${s==='base'?'':`?state=${s}`}`);
  void navigate({id:current.id,state:s},history.state?.dogmeetIndex??0);
 }
 useEffect(()=>{
  const scheduled=timers.current;
  history.replaceState({dogmeetIndex:0},'',location.href);
  const onHistory=()=>{
   const index=history.state?.dogmeetIndex??nav.current.index+1;
   if(history.state?.dogmeetIndex==null)history.replaceState({dogmeetIndex:index},'',location.href);
   void navigate(parseRoute(),index);
  };
  const motionQuery=matchMedia('(prefers-reduced-motion: reduce)');
  const preference=()=>{skipPageTransition();document.getAnimations().forEach(a=>a.cancel())};
  motionQuery.addEventListener('change',preference);
  const pointer=()=>{nav.current.keyboard=false;document.documentElement.dataset.motionInput='pointer'};
  const keyboard=()=>{nav.current.keyboard=true;document.documentElement.dataset.motionInput='keyboard'};
  window.addEventListener('hashchange',onHistory);window.addEventListener('popstate',onHistory);
  window.addEventListener('pointerdown',pointer);window.addEventListener('keydown',keyboard);
  return()=>{
   window.removeEventListener('hashchange',onHistory);window.removeEventListener('popstate',onHistory);
   window.removeEventListener('pointerdown',pointer);window.removeEventListener('keydown',keyboard);
   motionQuery.removeEventListener('change',preference);
   scheduled.forEach(clearTimeout);clearTimeout(toastTimer.current);skipPageTransition();
  };
 },[navigate]);
 useLayoutEffect(()=>{
  document.title=`${screen.title} · Dogmeet`;
  if(sheet&&dialog.current){
   if(!dialog.current.open)dialog.current.showModal();
   dialog.current.scrollTop=0;
   dialog.current.querySelector('.sheet-header button')?.focus({preventScroll:true});
  }else if(!sheet)heading.current?.focus({preventScroll:true});
 },[id,sheet,screen.title]);
 useEffect(()=>{sessionStorage.setItem('dogmeet.prototype.link-version',String(linkVersion))},[linkVersion]);
 function notify(message){
  clearTimeout(toastTimer.current);
  const version=++toastVersion.current;
  toastRef.current?.getAnimations().forEach(a=>a.cancel());
  setToast(message);
  toastTimer.current=setTimeout(async()=>{
   const element=toastRef.current;
   if(element?.animate){
    await element.animate([{opacity:1,transform:'translate(-50%,0)'},{opacity:0,transform:reducedMotion()?'translate(-50%,0)':'translate(-50%,8px)'}],{duration:reducedMotion()?100:120,easing:'cubic-bezier(0.23,1,0.32,1)',fill:'forwards'}).finished.catch(()=>{});
   }
   if(version===toastVersion.current)setToast('');
  },2400);
 }
 function complete(fn){variant('loading');timers.current.push(setTimeout(()=>{fn?.();variant('success')},400));}
 function reset(){setPets(initialPets);setOtherPets([richie]);setWalks(initialWalks);setRequests(initialRequests);setSavedLocation(initialLocation);setLoc(initialLocation);setLocations(locations);setDraft(defaultDraft);setPetId('bonya');setWalkId('w3');setRequestId('r1');setPeriod('Все');setQuery('');setGuided(false);setUsedLink(false);setEnabled(false);setLinkVersion(1);setPetDraft({name:'',owner:'',breed:'',photo:'/dog-placeholder.webp'});go('nearby');}
 function startWalk(){setDraft(defaultDraft);setGuided(false);setFormReturn('announce');go(pets.length?'announce':'pet-required');}
 function editPet(p=currentPet,admin=false){setPetId(p.id);setPetDraft({...p});go(admin?'admin-edit':'edit-pet');}
 function editWalk(){setDraft({...currentWalk});setFormReturn('edit-walk');go('edit-walk');}
 function validate(values,limits={}){const errors={};Object.entries(values).forEach(([key,value])=>{if(!value?.trim()||!/[\p{L}\p{N}]/u.test(value))errors[key]='Заполните это поле';else if(value.length>(limits[key]||80))errors[key]=`Не больше ${limits[key]} символов`});setErrors(errors);if(Object.keys(errors).length){requestAnimationFrame(()=>document.querySelector('[aria-invalid="true"]')?.focus());return false}return true}
 const errorFor=(key)=>formErrors[key]||(state==='validation'?'Проверьте это поле перед сохранением':'');

 function row(title,sub,icon,onClick,extra){const Icon=icon||ChevronRight;return <button type="button" className="menu-row" onClick={onClick}><Icon aria-hidden="true"/><span><strong>{title}</strong>{sub&&<small>{sub}</small>}</span>{extra||<ChevronRight aria-hidden="true"/>}</button>}
 function petFace(p,size=''){return <img data-pet-photo={p.id} className={`pet-face ${size}`} src={p.photo} alt={`Собака ${p.name}`}/>}
 function PetRows({admin=false,choose=false}){return <div className="pet-rows">{(admin?allPets:pets).filter(p=>!query||p.name.toLowerCase().includes(query.toLowerCase())).map(p=><button type="button" className="pet-row" key={p.id} onClick={()=>{setPetId(p.id);if(choose){setDraft({...draft,petId:p.id});go(formReturn)}else if(admin)editPet(p,true);else go('pet',p.shared?'shared':'base')}}>{petFace(p)}<span><strong>{p.name}</strong><small>{p.breed} · {p.owner}</small><em>{p.shared?'Общий питомец':'Ваш питомец'}</em></span>{choose&&draft.petId===p.id?<Check/>:<ChevronRight/>}</button>)}</div>}
 function WalkList({mine=false,preview=false}){const items=walks.filter(w=>mine?w.mine:w.schedule!=='Завтра'&&w.complex===savedLocation.complex).filter(w=>mine||period==='Все'||(period==='Утро'?+w.time.slice(0,2)<12:period==='День'?+w.time.slice(0,2)>=12&&+w.time.slice(0,2)<18:+w.time.slice(0,2)>=18)).sort((a,b)=>a.time.localeCompare(b.time));if(!items.length)return Empty();return <div className="timeline">{items.map(w=>{const p=findPet(w.petId);return <article className="walk-row" key={w.id}><div className="time-column"><strong>{w.time}</strong><span>{w.schedule==='Ежедневно'?'Каждый день':w.schedule}</span><i/></div><button type="button" className="walk-summary" onClick={()=>{setWalkId(w.id);setPetId(w.petId);go(mine?'walk-actions':'walk')}} tabIndex={preview?-1:0}>{petFace(p)}<span className="walk-person"><strong>{p.name}</strong><small>{p.owner} · {p.breed}</small></span><span className="walk-place"><MapPin/>{w.place}</span><span className="walk-comment"><MessageCircle aria-hidden="true"/>{w.comment||'Присоединяйтесь к прогулке'}</span>{mine&&<span className="text-link">Управлять <ChevronRight/></span>}</button></article>})}</div>}
 function Empty(){const petRelated=['pets','choose-pet','admin-pets'].includes(id);const isReq=id==='requests';const adminEmpty=id==='admin-pets';return <div className="state-block"><PawPrint className="state-icon"/><h2>{petRelated?'Пока ни одного питомца':isReq?'Все заявки разобраны':id==='location'?'Локация ещё не добавлена':id==='choose-place'?'Такого места пока нет':'Здесь пока тихо'}</h2><p>{petRelated?'Добавьте питомца, чтобы сообщать о прогулках.':isReq?'Новые предложения жителей появятся здесь.':id==='choose-place'?'Укажите своё место встречи. Соседи увидят его в объявлении.':'Сообщите, когда пойдёте гулять. Компания начинается с вас.'}</p><Button onClick={()=>{if(isReq||adminEmpty)go('admin');else if(id==='location')go('request');else if(id==='choose-place'){setQuery('');variant('base')}else if(petRelated){setPetDraft({name:'',owner:'',breed:'',photo:'/dog-placeholder.webp'});go('new-pet')}else startWalk()}}>{isReq||adminEmpty?'К управлению':id==='location'?'Предложить локацию':id==='choose-place'?'Указать своё место':petRelated?'Добавить питомца':'Сообщить о прогулке'}</Button>{id==='nearby'&&<Button variant="quiet" onClick={()=>{setPeriod('Все');variant('base')}}>Показать весь день</Button>}</div>}
 function Scenario({children}){if(state==='loading')return <div className="state-block" role="status" aria-live="polite" aria-busy="true"><div className="loader"/><h2>{['nearby','pets','plans','requests','admin-pets'].includes(id)?'Загружаем…':'Сохраняем…'}</h2><p>Подождите, это займёт несколько секунд.</p><div className="skeleton"/><div className="skeleton short"/><Button variant="quiet" onClick={()=>{timers.current.splice(0).forEach(clearTimeout);variant('base')}}>Вернуться</Button></div>;if(state==='error')return <div className="state-block" role="alert"><CircleAlert className="state-icon"/><h2>{id==='admin-login'?'Не удалось войти':['nearby','plans','pets','requests','admin-pets','choose-pet','choose-place','admin'].includes(id)?'Не получилось загрузить':'Не удалось сохранить'}</h2><p>{id==='admin-login'?'Проверьте логин и пароль. Данные формы сохранены.':'Проверьте соединение и попробуйте ещё раз. Ваши изменения не потеряны.'}</p><Button onClick={()=>variant('base')}><RefreshCw/>Повторить</Button><Button variant="quiet" onClick={back}>Назад</Button></div>;if(state==='empty')return Empty();if(state==='success'){const [title,text]=successCopy[id]||['Готово','Изменения сохранены.'];return <div className="state-block success" role="status"><CheckCircle2 className="state-icon"/><h2>{title}</h2><p>{text}</p>{['announce','edit-walk'].includes(id)&&<div className="receipt"><strong>{draft.time} · {draft.schedule}</strong><span>{draft.place}</span><small>{findPet(draft.petId).name} · {savedLocation.complex}</small></div>}<Button onClick={()=>go(guided&&id==='new-pet'?'announce':nextAfter[id]||'nearby')}>{guided&&id==='new-pet'?'Продолжить прогулку':['announce','edit-walk','delete-walk'].includes(id)?'Посмотреть мои планы':id==='request'?'Выбрать другой район':id==='admin-login'?'Открыть управление':'Готово'}<ArrowRight/></Button></div>}return children}
 function submitPet(e){e.preventDefault();const values={name:petDraft.name,owner:petDraft.owner,breed:petDraft.breed};if(!validate(values,{name:40,owner:60,breed:20})||photoError)return;complete(()=>{let saved;if(id==='new-pet'){saved={...petDraft,id:`pet-${Date.now()}`,shared:false};setPets(ps=>[...ps,saved]);}else {saved={...currentPet,...petDraft};if(id==='admin-edit'&&otherPets.some(p=>p.id===saved.id)){setOtherPets(ps=>ps.map(p=>p.id===saved.id?saved:p))}else setPets(ps=>ps.some(p=>p.id===saved.id)?ps.map(p=>p.id===saved.id?saved:p):[...ps,saved]);}setPetId(saved.id);setDraft(d=>({...d,petId:saved.id}));});}
 function handlePhoto(e){const file=e.target.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){setPhotoError('Нужен JPG, PNG или WebP до 10 МБ.');return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{setPetDraft(p=>({...p,photo:String(reader.result)}));setPhotoError('');notify('Фотография выбрана')};img.onerror=()=>setPhotoError('Файл не удалось прочитать как фотографию. Выберите другой.');img.src=String(reader.result)};reader.onerror=()=>setPhotoError('Не удалось прочитать файл. Попробуйте другой.');reader.readAsDataURL(file);}
 function submitWalk(e){e.preventDefault();if(!validate({petId:draft.petId,place:draft.place,time:draft.time},{place:40}))return;if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(draft.time)){setErrors({time:'Укажите время от 00:00 до 23:59'});return}complete(()=>setWalks(ws=>id==='edit-walk'?ws.map(w=>w.id===walkId?{...w,...draft}:w):[...ws,{...draft,id:`w-${Date.now()}`,mine:true,complex:savedLocation.complex}]));}
 async function copyText(text){try{await navigator.clipboard.writeText(text);variant('success')}catch{notify('Не удалось скопировать. Выделите ссылку и скопируйте вручную.')}}
 const shareLink=`${location.origin}/#accept?pet=${currentPet.id}&token=demo-${linkVersion}`;
 function deletePet(){complete(()=>{setPets(ps=>ps.filter(p=>p.id!==currentPet.id));if(currentPet.shared&&id!=='admin-delete')setOtherPets(ps=>[...ps.filter(p=>p.id!==currentPet.id),currentPet]);if(id==='admin-delete')setOtherPets(ps=>ps.filter(p=>p.id!==currentPet.id));if(!currentPet.shared||id==='admin-delete')setWalks(ws=>ws.filter(w=>w.petId!==currentPet.id))});}
 function content(id=route.id){switch(id){
 case 'welcome':return <div className="welcome"><div className="brand"><PawPrint/>dogmeet<span>Встретимся во дворе</span></div><h1 ref={heading} tabIndex="-1">Хорошая прогулка<br/>начинается<br/><em>с компании.</em></h1><div className="welcome-photo"><img src="/walk-hero.webp" alt="Хозяйка и собака гуляют во дворе"/><div className="photo-caption"><span>Знакомые места.</span><strong>Новые друзья.</strong></div></div><p>Узнайте, кто гуляет рядом, и расскажите соседям о своих планах.</p><Button onClick={()=>go('guide')}>Найти компанию<ArrowRight/></Button><small className="center-note">Без регистрации. Начнём с вашего района.</small></div>;
 case 'guide':return <><div className="guide-symbol"><Compass/></div><h2>Останемся<br/>на связи</h2><p>Откройте Dogmeet в обычном браузере, чтобы ваши питомцы и планы сохранялись в этой сессии.</p><div className="segmented">{['iPhone','Android'].map(v=><button type="button" aria-pressed={(state==='android'?'Android':platform)===v} key={v} onClick={()=>{setPlatform(v);if(state==='android')variant('base')}}>{v}</button>)}</div><div className="instruction"><span>1</span><div><strong>{(state==='android'?'Android':platform)==='iPhone'?'Нажмите значок компаса':'Откройте меню с тремя точками'}</strong><p>{(state==='android'?'Android':platform)==='iPhone'?'Внизу окна Telegram выберите открытие в Safari.':'В верхнем углу выберите «Открыть в браузере».'}</p></div></div><div className="instruction"><span>2</span><div><strong>Продолжите здесь</strong><p>Если вы уже в Safari или Chrome, просто нажмите кнопку ниже.</p></div></div><Button onClick={()=>go('location')}>Продолжить<ArrowRight/></Button></>;
 case 'location':{const cities=[...new Set(availableLocations.map(l=>l.city))];const districts=[...new Set(availableLocations.filter(l=>l.city===loc.city).map(l=>l.district))];const complexes=availableLocations.filter(l=>l.city===loc.city&&l.district===loc.district).map(l=>l.complex);return <><p className="lead">Компания начинается<br/>рядом с домом.</p><div className="location-preview"><MapPin/><strong>{loc.complex||'Ваш жилой комплекс'}</strong><span>{loc.city||'Выберите город'} · {loc.district||'Район'}</span></div><form onSubmit={e=>{e.preventDefault();if(validate(loc))complete(()=>setSavedLocation(loc))}} noValidate><Field errors={formErrors} forced={state==='validation'} label="Город" name="city" value={loc.city} options={cities} onChange={v=>setLoc({city:v,district:'',complex:''})}/><Field errors={formErrors} forced={state==='validation'} label="Район" name="district" value={loc.district} options={districts} onChange={v=>setLoc({...loc,district:v,complex:''})}/><Field errors={formErrors} forced={state==='validation'} label="Жилой комплекс" name="complex" value={loc.complex} options={complexes} onChange={v=>setLoc({...loc,complex:v})}/><Button type="submit">Показать прогулки<ArrowRight/></Button></form><Button variant="quiet" onClick={()=>go('request')}>Нет моего жилого комплекса</Button></>}
 case 'request':return <><p>Расскажите, где хотите гулять. Администратор рассмотрит заявку и добавит новую локацию.</p><form noValidate onSubmit={e=>{e.preventDefault();if(validate(req))complete(()=>setRequests(rs=>[...rs,{...req,id:`r-${Date.now()}`,date:'14 сентября, 19:15'}]))}}>{[['city','Город'],['district','Район'],['complex','Жилой комплекс']].map(([key,label])=><Field errors={formErrors} forced={state==='validation'} key={key} label={label} name={key} value={req[key]} onChange={v=>setReq({...req,[key]:v})}/>)}<div className="note"><Clock3/>Пока заявка на рассмотрении, можно выбрать соседний район.</div><Button type="submit">Отправить заявку<ArrowRight/></Button></form></>;
 case 'nearby':return <><div className="page-header nearby-toolbar"><div className="brand"><PawPrint aria-hidden="true"/>dogmeet</div><button type="button" className="location-switch" onClick={()=>{setLoc(savedLocation);go('location')}}><MapPin/><span>{savedLocation.complex}</span></button><button type="button" className="icon-button" aria-label="Мой район и настройки" onClick={()=>go('profile')}><MoreHorizontal/></button></div><div className="day-heading"><h1 ref={heading} tabIndex="-1">Кто сегодня<br/><em>на прогулку?</em></h1><span className="date-stamp"><strong>14</strong>сентября<br/>понедельник</span></div><div className="daily-summary"><div className="stacked-faces">{[richie,initialPets[1],initialPets[0]].map(p=><img key={p.id} src={p.photo} alt={p.name}/>)}</div><p>Знакомьтесь во дворе.<br/><strong>У каждого есть время для прогулки.</strong></p></div><div className="section-line"><h2>Сегодня рядом</h2><button type="button" className="filter-trigger" onClick={()=>{setTempPeriod(period);go('filters')}}><SlidersHorizontal/>{period==='Все'?'Весь день':period}</button></div>{WalkList({})}</>;
 case 'filters':return <><p>В какое время вам удобнее встретиться?</p><div className="option-list">{['Все','Утро','День','Вечер'].map((p,i)=><button type="button" key={p} aria-pressed={tempPeriod===p} onClick={()=>setTempPeriod(p)}><span><strong>{p==='Все'?'Весь день':p}</strong><small>{['Все прогулки сегодня','До 12:00','12:00–17:59','После 18:00'][i]}</small></span>{tempPeriod===p?<Check/>:i===3?<Moon/>:<Sun/>}</button>)}</div><Button onClick={()=>{setPeriod(tempPeriod);go('nearby')}}>Показать прогулки<ArrowRight/></Button></>;
 case 'walk':{const p=findPet(currentWalk.petId);return <><img className="portrait" src={p.photo} alt={p.name}/><div className="pet-title"><h2>{p.name}</h2><span>{p.breed}</span></div><p>Гуляет с {p.owner==='Анна'?'Анной':p.owner==='Мария'?'Марией':'Михаилом'}</p><div className="big-time"><Clock3/><strong>{currentWalk.time}</strong><span>{currentWalk.schedule}</span></div><div className="place-detail"><MapPin/><div><h3>{currentWalk.place}</h3><p>{savedLocation.complex}<br/>{savedLocation.city}, {savedLocation.district}</p></div></div><blockquote>«{currentWalk.comment||'Приходите гулять вместе'}»</blockquote><div className="note">Узнаете друг друга по питомцу. Встречайтесь в указанном месте.</div><Button onClick={currentWalk.mine?editWalk:startWalk}>{currentWalk.mine?'Изменить мою прогулку':'Сообщить о своей прогулке'}<ArrowRight/></Button></>}
 case 'announce':case 'edit-walk':return <><p>{id==='edit-walk'?'Поменялись планы? Обновите детали.':'Расскажите соседям, где вас найти.'}</p><form noValidate onSubmit={submitWalk}><button type="button" className="selected-pet" onClick={()=>{setFormReturn(id);setQuery('');go('choose-pet')}}>{petFace(findPet(draft.petId))}<span><small>Иду гулять с</small><strong>{findPet(draft.petId).name}</strong></span><ChevronDown/></button>{errorFor('petId')&&<p className="field-error">{errorFor('petId')}</p>}<div className="field"><span>Когда</span></div><div className="segmented">{['Сегодня','Завтра','Ежедневно'].map(s=><button type="button" key={s} aria-pressed={draft.schedule===s} onClick={()=>setDraft({...draft,schedule:s})}>{s}</button>)}</div><div className="walk-settings">{row('Время',draft.time,Clock3,()=>{setFormReturn(id);go('choose-time')})}{row('Место встречи',draft.place,MapPin,()=>{setFormReturn(id);setQuery('');go('choose-place')})}</div>{errorFor('place')&&<p className="field-error">{errorFor('place')}</p>}<label className="field"><span>Комментарий <small>необязательно</small></span><textarea value={draft.comment} maxLength={40} onChange={e=>setDraft({...draft,comment:e.target.value})} placeholder="Например, возьмём мячик"/><small className="counter">{draft.comment.length}/40</small></label><div className="note"><MapPin/>Прогулка появится в районе {savedLocation.complex}.</div><Button type="submit">{id==='edit-walk'?'Сохранить изменения':'Сообщить о прогулке'}<ArrowRight/></Button></form></>;
 case 'choose-pet':return <>{PetRows({choose:true})}<Button variant="quiet" onClick={()=>{setGuided(true);setPetDraft({name:'',owner:'',breed:'',photo:'/dog-placeholder.webp'});go('new-pet')}}><Plus/>Добавить питомца</Button></>;
 case 'choose-place':{const places=['Площадка у 3-го корпуса','Аллея вдоль пруда','Сквер у фонтана'].filter(p=>p.toLowerCase().includes(query.toLowerCase()));return <><label className="search-field"><Search/><input aria-label="Найти место" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Название места"/></label><div className="option-list">{places.map(p=><button type="button" key={p} onClick={()=>{setDraft({...draft,place:p});go(formReturn)}}><MapPin/><span>{p}</span>{draft.place===p?<Check/>:<ChevronRight/>}</button>)}</div>{!places.length&&<p>Совпадений нет. Укажите своё место ниже.</p>}<form noValidate onSubmit={e=>{e.preventDefault();if(validate({place:customPlace},{place:40})){setDraft({...draft,place:customPlace.trim()});go(formReturn)}}}><Field errors={formErrors} forced={state==='validation'} label="Или своё место встречи" name="place" maxLength={40} value={customPlace} placeholder="Например, у входа в сквер" onChange={setCustomPlace}/><Button type="submit">Выбрать это место<ArrowRight/></Button></form></>}
 case 'choose-time':return <><p>{draft.schedule==='Ежедневно'?'Встречаемся каждый день':'Встречаемся '+draft.schedule.toLowerCase()}</p><div className="time-picker"><Clock3/><label htmlFor="walk-time">Время начала прогулки</label><input id="walk-time" aria-label="Время начала прогулки" type="time" value={draft.time} onChange={e=>setDraft({...draft,time:e.target.value})}/></div><Button onClick={()=>{if(draft.time)go(formReturn);else setErrors({time:'Укажите время'})}}>Готово<Check/></Button>{formErrors.time&&<p role="alert">{formErrors.time}</p>}</>;
 case 'pet-required':return <><PawPrint className="state-icon"/><h2>Познакомимся<br/>с питомцем?</h2><p>Добавьте питомца, чтобы соседи знали, с кем вы выйдете гулять.</p><Button onClick={()=>{setGuided(true);setPetDraft({name:'',owner:'',breed:'',photo:'/dog-placeholder.webp'});go('new-pet')}}>Добавить питомца<Plus/></Button><Button variant="quiet" onClick={back}>Пока посмотреть прогулки</Button></>;
 case 'plans':return <><p>Ваши встречи сегодня, завтра<br/>и маленькие ежедневные традиции.</p>{WalkList({mine:true})}</>;
 case 'walk-actions':return <><div className="receipt"><strong>{currentWalk.time} · {currentWalk.schedule}</strong><span>{currentWalk.place}</span><small>{findPet(currentWalk.petId).name}</small></div>{row('Изменить прогулку',null,Pencil,editWalk)}{!findPet(currentWalk.petId).shared&&row('Поделиться питомцем',null,Share2,()=>{setPetId(currentWalk.petId);go('share')})}{row('Удалить прогулку',null,Trash2,()=>go('delete-walk'))}<Button variant="quiet" onClick={back}>Закрыть</Button></>;
 case 'delete-walk':return <><p>Прогулка в {currentWalk.time}, {currentWalk.place.toLowerCase()}, исчезнет из расписания.</p><p>Добавьте новую, когда снова соберётесь гулять.</p><Button variant="danger" onClick={()=>complete(()=>setWalks(ws=>ws.filter(w=>w.id!==walkId)))}>Удалить прогулку</Button><Button variant="quiet" onClick={back}>Оставить</Button></>;
 case 'pets':return <><p>Те, ради кого мы выходим<br/>из дома в любую погоду.</p>{PetRows({})}<div className="note"><Share2/>Питомцем можно поделиться с близким человеком и вместе планировать прогулки.</div></>;
 case 'pet':return <><img data-pet-photo={currentPet.id} className="portrait" src={currentPet.photo} alt={currentPet.name}/><div className="pet-title"><h2>{currentPet.name}</h2><span>{currentPet.shared?'Общий питомец':'Ваш питомец'}</span></div><dl className="facts"><div><dt>Порода</dt><dd>{currentPet.breed}</dd></div><div><dt>Хозяин</dt><dd>{currentPet.owner}</dd></div></dl>{row('Изменить данные','Имя, порода и фото',Pencil,()=>editPet())}{!currentPet.shared&&row('Поделиться питомцем','Для совместных прогулок',Share2,()=>go('share'))}{row(currentPet.shared?'Убрать из моего списка':'Удалить питомца',currentPet.shared?'У владельца питомец останется':'Вместе с его прогулками',Trash2,()=>go('delete-pet',currentPet.shared?'shared':'base'))}</>;
 case 'new-pet':case 'edit-pet':case 'admin-edit':return <><p>{id==='new-pet'?'Соседи запомнят не анкету, а добрую морду.':'Актуальные данные помогут узнать вас на прогулке.'}</p><form onSubmit={submitPet} noValidate><button type="button" className="photo-editor" onClick={()=>{setPhotoReturn(id);go('photo')}}><img src={petDraft.photo} alt="Фотография питомца"/><span><Camera/>{id==='new-pet'?'Выбрать фотографию':'Изменить фотографию'}</span></button><Field errors={formErrors} forced={state==='validation'} label="Имя питомца" name="name" maxLength={40} value={petDraft.name} placeholder="Например, Боня" onChange={v=>setPetDraft({...petDraft,name:v})}/><Field errors={formErrors} forced={state==='validation'} label="Имя хозяина" name="owner" maxLength={60} value={petDraft.owner} placeholder="Например, Анна" onChange={v=>setPetDraft({...petDraft,owner:v})}/><Field errors={formErrors} forced={state==='validation'} label="Порода" name="breed" maxLength={20} value={petDraft.breed} placeholder="Например, корги" onChange={v=>setPetDraft({...petDraft,breed:v})}/><Button type="submit">{id==='new-pet'?'Добавить питомца':'Сохранить изменения'}<ActionIcon done={Object.values({name:petDraft.name,owner:petDraft.owner,breed:petDraft.breed}).every(v=>/[\p{L}\p{N}]/u.test(v))}/></Button></form>{id==='admin-edit'&&<Button variant="quiet danger-text" onClick={()=>go('admin-delete')}><Trash2/>Удалить питомца</Button>}</>;
 case 'photo':return <><img className="photo-preview" src={petDraft.photo} alt="Предпросмотр фотографии"/><label className="upload"><Camera/><strong>Выбрать файл</strong><input type="file" accept="image/jpeg,image/png,image/webp" onChange={handlePhoto}/></label><p>JPG, PNG или WebP до 10 МБ. Выберите снимок, на котором хорошо видно питомца.</p>{(photoError||state==='validation')&&<p className="field-error" role="alert">{photoError||'Этот файл не подходит. Выберите JPG, PNG или WebP до 10 МБ.'}</p>}<div className="sample-photos" aria-label="Фотографии для примерки">{initialPets.concat(richie).map(p=><button type="button" key={p.id} onClick={()=>{setPetDraft({...petDraft,photo:p.photo});setPhotoError('');if(state==='validation')variant('base')}} aria-label={`Выбрать фото ${p.name}`}><img src={p.photo} alt={p.name}/></button>)}</div><Button onClick={()=>go(photoReturn)}>Использовать фото<Check/></Button></>;
 case 'delete-pet':case 'admin-delete':return <>{petFace(currentPet,'large')}<h2>{currentPet.shared&&id!=='admin-delete'?'Убрать из списка?':`Удалить ${currentPet.name==='Боня'?'Боню':currentPet.name}?`}</h2><p>{currentPet.shared&&id!=='admin-delete'?'Питомец исчезнет только из вашего списка. У владельца и других близких он останется.':'Питомец и все его прогулки будут удалены. Это действие нельзя отменить.'}</p><Button variant="danger" onClick={deletePet}>{currentPet.shared?'Убрать из списка':'Удалить питомца'}</Button><Button variant="quiet" onClick={back}>Оставить</Button></>;
 case 'share':return <><h2>Один питомец.<br/>Общие планы.</h2><p>Передайте ссылку близкому человеку: он сможет управлять питомцем {currentPet.name} и сообщать о прогулках.</p><label className="field"><span>Одноразовая ссылка</span><input readOnly value={shareLink} onFocus={e=>e.target.select()}/></label><Button onClick={()=>copyText(shareLink)}><Copy/>Скопировать ссылку</Button><p className="small-note">Ссылка действует для одного добавления. Реальная отправка не выполняется.</p><Button variant="quiet" onClick={()=>go('rotate-link')}><RefreshCw/>Получить новую ссылку</Button></>;
 case 'rotate-link':return <><RefreshCw className="state-icon"/><h2>Заменить ссылку?</h2><p>Старая ссылка перестанет действовать. Доступ тех, кто уже добавил питомца, сохранится.</p><Button onClick={()=>complete(()=>{setLinkVersion(v=>v+1);setUsedLink(false)})}>Получить новую ссылку</Button><Button variant="quiet" onClick={back}>Сохранить прежнюю</Button></>;
 case 'accept':if(state==='expired'||state==='used'||usedLink||(acceptParams.has('token')&&acceptParams.get('token')!==`demo-${linkVersion}`))return <div className="state-block"><CircleAlert className="state-icon"/><h2>{(state==='expired'||(acceptParams.has('token')&&acceptParams.get('token')!==`demo-${linkVersion}`))?'Ссылка недействительна':'Ссылка уже использована'}</h2><p>{state==='expired'?'Владелец мог получить новую ссылку. Попросите его поделиться ещё раз.':'По этой ссылке питомец уже добавлен. Для другого человека нужна новая ссылка.'}</p><Button onClick={()=>go('nearby')}>К прогулкам</Button></div>;return <><p className="lead">{invitedPet.owner} делится<br/>с вами питомцем.</p><img className="portrait" src={invitedPet.photo} alt={invitedPet.name}/><div className="pet-title"><h2>{invitedPet.name}</h2><span>{invitedPet.breed}</span></div><p>Вы сможете менять данные питомца {invitedPet.name} и сообщать о прогулках вместе с владельцем.</p><Button onClick={()=>{if(pets.some(p=>p.id===invitedPet.id))go('already-added');else complete(()=>{setPets(ps=>[...ps,{...invitedPet,shared:true}]);setUsedLink(true)})}}>Добавить к моим питомцам<Plus/></Button><Button variant="quiet" onClick={()=>go('nearby')}>Отказаться</Button></>;
 case 'already-added':return <>{petFace(richie,'large')}<h2>Вы уже знакомы</h2><p>Этот питомец уже есть в вашем списке. Добавлять его снова не нужно.</p><Button onClick={()=>go('pets')}>К моим питомцам</Button></>;
 case 'profile':return <><div className="profile-banner"><MapPin/><h2>{savedLocation.complex}</h2><p>{savedLocation.city} · {savedLocation.district}</p><Button variant="light" onClick={()=>{setLoc(savedLocation);go('location')}}>Изменить локацию<ArrowRight/></Button></div>{row('Мои планы','Разовые и ежедневные прогулки',CalendarDays,()=>go('plans'))}{row('Мои питомцы','Свои и общие',PawPrint,()=>go('pets'))}{row('Связь с разработчиком','Telegram · @kuznetsoviv',ExternalLink,()=>go('contact'))}<p className="small-note">Данные привязаны к этому браузеру. Сохраните ссылку на питомца, чтобы поделиться доступом.</p></>;
 case 'contact':return <><h2>Есть идея<br/>или вопрос?</h2><p>Разработчик Dogmeet — в Telegram. Напишите, что можно сделать удобнее.</p><div className="receipt"><strong>@kuznetsoviv</strong><span>t.me/kuznetsoviv</span></div><Button onClick={()=>copyText('https://t.me/kuznetsoviv')}><Copy/>Скопировать контакт</Button><p className="small-note">Прототип ничего не отправляет и не открывает мессенджер автоматически.</p></>;
 case 'admin-login':return <><ShieldCheck className="state-icon"/><h2>Для тех, кто<br/>заботится о дворе</h2><p>Войдите, чтобы разбирать заявки жителей и управлять питомцами.</p><form onSubmit={e=>{e.preventDefault();if(validate(login)){if(login.user==='demo'&&login.password==='dogmeet')complete();else {setErrors({password:'Для прототипа: demo / dogmeet'});}}}} noValidate><Field errors={formErrors} forced={state==='validation'} label="Логин" name="user" value={login.user} onChange={v=>setLogin({...login,user:v})}/><Field errors={formErrors} forced={state==='validation'} label="Пароль" name="password" type="password" value={login.password} onChange={v=>setLogin({...login,password:v})}/><Button type="submit">Войти<ArrowRight/></Button></form><p className="small-note">Демонстрационный доступ: demo / dogmeet</p></>;
 case 'admin':return <><div className="admin-summary"><ShieldCheck/><h2>Всё начинается<br/>с хорошего района.</h2><p>{requests.length} заявки ждут вашего решения.</p></div>{row('Заявки жителей','Добавление новых локаций',MapPin,()=>go('requests'),<span className="count">{requests.length}</span>)}{row('Все питомцы','Посмотреть и изменить',PawPrint,()=>{setQuery('');go('admin-pets')})}{row('Уведомления',enabled?'Включены':'Отключены',Bell,()=>go('notifications'))}{row('На главную','Расписание прогулок',Compass,()=>go('nearby'))}{row('Выйти',null,LogOut,()=>go('admin-logout'))}</>;
 case 'requests':return <><p>Жители предлагают новые места<br/>для совместных прогулок.</p>{requests.length?requests.map(r=><article className="request-row" key={r.id}><div className="section-line"><span className="tag">Новая заявка</span><small>{r.date}</small></div><h2>{r.complex}</h2><p>{r.city} · {r.district}</p><div className="two-actions"><Button onClick={()=>{setRequestId(r.id);go('approve')}}><Check/>Добавить</Button><Button variant="secondary" onClick={()=>{setRequestId(r.id);go('reject')}}>Отклонить</Button></div></article> ):Empty()}</>;
 case 'approve':case 'reject':return <><MapPin className="state-icon"/><h2>{id==='approve'?'Ещё один район<br/>для встреч':'Отклонить заявку?'}</h2><div className="receipt"><strong>{currentRequest.complex}</strong><span>{currentRequest.city} · {currentRequest.district}</span></div><p>{id==='approve'?'Локация появится в списке. Жители смогут выбрать её для прогулок.':'Заявка будет удалена без добавления локации.'}</p><Button variant={id==='reject'?'danger':''} onClick={()=>complete(()=>{if(id==='approve')setLocations(ls=>[...ls,currentRequest]);setRequests(rs=>rs.filter(r=>r.id!==requestId))})}>{id==='approve'?'Добавить локацию':'Отклонить заявку'}</Button><Button variant="quiet" onClick={back}>Отмена</Button></>;
 case 'admin-pets':return <><label className="search-field"><Search/><input aria-label="Найти питомца" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Найти по имени"/></label>{PetRows({admin:true})}{!allPets.some(p=>p.name.toLowerCase().includes(query.toLowerCase()))&&<p role="status">Никого не нашли. Попробуйте другое имя.</p>}</>;
 case 'notifications':return <><Bell className="state-icon"/><h2>Не пропускайте<br/>новые заявки</h2><p>Получайте уведомление, когда житель предлагает добавить новую локацию.</p>{['denied','unsupported'].includes(state)?<div className="note"><CircleAlert/>{state==='denied'?'Браузер запретил уведомления. Разрешите их в настройках сайта, затем повторите.':'Этот браузер не поддерживает уведомления. Проверяйте заявки в панели управления.'}</div>:<button type="button" className="toggle-row" role="switch" aria-checked={enabled} onClick={()=>{setEnabled(!enabled);notify(enabled?'Уведомления отключены':'Уведомления включены')}}><span><strong>Новые заявки</strong><small>{enabled?'Уведомления включены':'Уведомления отключены'}</small></span><i className={enabled?'on':''}/></button>}<Button onClick={()=>{if(['denied','unsupported'].includes(state))variant('base');else complete(()=>setEnabled(true))}}>{['denied','unsupported'].includes(state)?'Проверить ещё раз':'Включить уведомления'}</Button><p className="small-note">В прототипе разрешение браузера не запрашивается; показаны локальные состояния.</p></>;
 case 'admin-logout':return <><LogOut className="state-icon"/><h2>Закончить работу?</h2><p>Для возвращения в управление потребуется снова ввести логин и пароль.</p><Button onClick={()=>complete(()=>setLogin({user:'',password:''}))}>Выйти</Button><Button variant="quiet" onClick={back}>Остаться</Button></>;
 default:return null;
 }}
 const hasNav=['nearby','plans','pets'].includes(pageId);
 const hideHeader=['nearby','welcome'].includes(pageId);
 return <div className={`studio ${capture?'capture':''} ${new URLSearchParams(location.search).get('nav')==='floating'?'floating-nav':''}`}><aside className="inspector"><a className="studio-brand" href="/gallery.html">Dogmeet / обзор макетов<ArrowRight/></a><a href="/#nearby">Главная · исходное меню</a><a href="/?nav=floating#nearby">Главная · плавающее меню</a><p>Изолированный прототип<br/>Все данные вымышлены</p><label>Экран<select value={id} onChange={e=>go(e.target.value)}>{screens.map(s=><option value={s.id} key={s.id}>{s.title}</option>)}</select></label><label>Состояние<select value={state} onChange={e=>variant(e.target.value)}>{screen.states.map(s=><option key={s} value={s}>{states[s]}</option>)}</select></label><button type="button" onClick={reset}>Сбросить моковые данные</button><a href="/#admin-login">Открыть админку</a><small>390 px · мобильный web<br/>Переключатели находятся вне продукта.</small></aside><div className={`phone ${sheet?'has-sheet':''}`}><div className="status-bar" aria-hidden="true"><span>9:41</span><div><span className="signal"/><span className="wifi"/><span className="battery"/></div></div><main className={hasNav?'with-nav':''} data-motion-page={pageId} inert={sheet}>{!hideHeader&&<header className={`page-header ${['plans','pets'].includes(pageId)?'nearby-toolbar':''}`}>{!['plans','pets'].includes(pageId)&&<button type="button" className="icon-button" aria-label="Назад" onClick={back}><ArrowLeft/></button>}{pageId.startsWith('admin')||['requests','approve','reject','notifications'].includes(pageId)?<span>Управление Dogmeet</span>:<span className="brand"><PawPrint aria-hidden="true"/>dogmeet</span>}{['plans','pets'].includes(pageId)&&<button type="button" className="location-switch" onClick={()=>{setLoc(savedLocation);go('location')}}><MapPin/><span>{savedLocation.complex}</span></button>}{hasNav&&<button type="button" className="icon-button" aria-label="Мой район и настройки" onClick={()=>go('profile')}><MoreHorizontal/></button>}</header>}{!hideHeader&&<h1 ref={heading} tabIndex="-1">{pageScreen.title}</h1>}<div className="scenario-content">{sheet?content(pageId):Scenario({children:content()})}</div></main>{hasNav&&<div className="nav-shade" aria-hidden="true"/>}{hasNav&&<nav className="bottom-nav" aria-label="Основная навигация"><div className="nav-tabs" data-active={pageId}><span className="nav-indicator" aria-hidden="true"/>{[['nearby','Рядом',Compass],['plans','Мои планы',CalendarDays],['pets','Питомцы',PawPrint]].map(([target,label,Icon])=><button type="button" key={target} aria-current={pageId===target?'page':undefined} onClick={()=>go(target)}><span className="nav-label" style={{viewTransitionName:`dogmeet-label-${target}`}}><Icon/><span>{label}</span></span></button>)}</div>{pageId==='pets'?<DockAddButton aria-label="Добавить питомца" title="Добавить питомца" onClick={()=>{setGuided(false);setPetDraft({name:'',owner:'',breed:'',photo:'/dog-placeholder.webp'});go('new-pet')}}><Plus aria-hidden="true"/></DockAddButton>:pageId==='plans'?<DockAddButton aria-label="Новая прогулка" title="Новая прогулка" onClick={startWalk}><Plus aria-hidden="true"/></DockAddButton>:<DockAddButton aria-label="Я иду гулять" title="Я иду гулять" onClick={startWalk}><Plus aria-hidden="true"/></DockAddButton>}</nav>}{sheet&&<dialog ref={dialog} className={`sheet ${id==='share'?'sheet--share ':''}${id==='pet-required'?'sheet--pet-required':''}`} aria-labelledby={id==='share'||id==='pet-required'?undefined:'sheet-title'} aria-label={id==='share'?screen.title:id==='pet-required'?'Сначала питомец':undefined} onCancel={e=>{e.preventDefault();back()}}><div className="sheet-grip"/><div className="sheet-header">{id!=='share'&&id!=='pet-required'&&<h1 id="sheet-title">{screen.title}</h1>}<button type="button" className="icon-button" aria-label="Закрыть панель" onClick={back}><X/></button></div><div className="sheet-content">{Scenario({children:content()})}</div></dialog>}{toast&&<div ref={toastRef} className="toast" role="status"><CheckCircle2/>{toast}</div>}</div></div>;
}
createRoot(document.getElementById('root')).render(<App/>);
